import 'package:build/build.dart';
import 'package:dart_style/dart_style.dart';
import 'package:glob/glob.dart';
import 'package:path/path.dart' as p;
import 'package:pub_semver/pub_semver.dart';

/// Reads an `output` option from build.yaml (defaults to "routes.g.dart")
/// and uses that for buildExtensions and writing the file.
Builder aggregateAppRoutes(BuilderOptions options) =>
    AggregateAppRoutesBuilder(options);

/// Aggregates the `$appRoutes` getters generated by go_router_builder into a
/// single `$aggregatedRoutes` getter.
class AggregateAppRoutesBuilder implements Builder {
  static const _defaultPath = 'routes.g.dart';

  /// go_router_builder emits this part only for libraries declaring typed
  /// routes, and every such part contains a `$appRoutes` getter.
  static const _partExtension = '.go_router.g.part';
  static final _partsGlob = Glob('lib/**$_partExtension');
  static final _nonIdentifierChars = RegExp('[^A-Za-z0-9_]');

  /// Output path relative to `lib/`, e.g. "navigation/routes.g.dart".
  final String outputPath;

  AggregateAppRoutesBuilder(BuilderOptions options)
    : outputPath = _parseOutputPath(options.config['output']);

  @override
  Map<String, List<String>> get buildExtensions => {
    r'$lib$': [outputPath],
  };

  @override
  Future<void> build(BuildStep buildStep) async {
    final package = buildStep.inputId.package;

    final libraries =
        await buildStep.findAssets(_partsGlob).map(_libraryPath).toList();
    libraries.sort();

    final prefixes = <String>{};
    final imports = StringBuffer();
    final spreads = StringBuffer();

    for (final library in libraries) {
      final basePrefix = '_${p.url.withoutExtension(library)}'.replaceAll(
        _nonIdentifierChars,
        '_',
      );
      var prefix = basePrefix;
      for (var i = 1; !prefixes.add(prefix); i++) {
        prefix = '$basePrefix$i';
      }

      imports.writeln("import 'package:$package/$library' as $prefix;");
      spreads.writeln('...$prefix.\$appRoutes,');
    }

    final code = '''
// GENERATED by go_router_aggregator - do NOT edit by hand - contents will be overridden
// ignore_for_file: type=lint
import 'package:go_router/go_router.dart';

$imports
List<RouteBase> get \$aggregatedRoutes => [
$spreads];
''';

    final formatter = DartFormatter(
      languageVersion: await _languageVersion(buildStep, package),
    );

    await buildStep.writeAsString(
      AssetId(package, 'lib/$outputPath'),
      formatter.format(code),
    );
  }

  /// Maps `lib/foo/bar.go_router.g.part` to `foo/bar.dart`.
  static String _libraryPath(AssetId part) =>
      '${part.path.substring(4, part.path.length - _partExtension.length)}.dart';

  static Future<Version> _languageVersion(
    BuildStep buildStep,
    String package,
  ) async {
    final packageVersion =
        (await buildStep.packageConfig)[package]?.languageVersion;
    if (packageVersion == null) {
      return DartFormatter.latestLanguageVersion;
    }

    final version = Version(packageVersion.major, packageVersion.minor, 0);

    return version > DartFormatter.latestLanguageVersion
        ? DartFormatter.latestLanguageVersion
        : version;
  }

  static String _parseOutputPath(Object? option) {
    if (option == null) {
      return _defaultPath;
    }

    if (option is! String) {
      throw ArgumentError.value(option, 'output', 'Must be a string');
    }

    final trimmed = option.trim();
    final normalized = p.url.normalize(trimmed);

    String? error;
    if (trimmed.isEmpty) {
      error = 'Must not be empty';
    } else if (p.url.isAbsolute(normalized)) {
      error = 'Must be relative to lib/';
    } else if (normalized == '..' || normalized.startsWith('../')) {
      error = 'Must point inside lib/';
    } else if (normalized.startsWith('lib/')) {
      error = 'Must be relative to lib/ and not start with "lib/"';
    } else if (!normalized.endsWith('.dart')) {
      error = 'Must end with ".dart"';
    }

    if (error != null) {
      throw ArgumentError.value(option, 'output', error);
    }

    return normalized;
  }
}
